// "Nouvelle personne": the kind, the name and, optionally, the organisation and
// the group. Everything else is filled in from the fiche. The pseudonym is
// generated by the server and stays whatever the name becomes.

import { useState } from "react"
import { useMutation, useQueryClient } from "@tanstack/react-query"
import { toast } from "sonner"

import { Alerts, Field, NativeSelect } from "@/components/settings/fields"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { t } from "@/i18n"
import { KINDS, flattenGroups, invalidateRegister, kindLabel, personsApi, type GroupNode, type PersonKind } from "@/lib/persons-api"
import { plainError } from "@/lib/persons-errors"
import { cn } from "@/lib/utils"

export function NewPersonDialog({
  open,
  onClose,
  tree,
  defaultGroup,
  defaultKind,
  onCreated,
}: {
  open: boolean
  onClose: () => void
  tree: GroupNode[]
  defaultGroup: string | null
  defaultKind: PersonKind
  onCreated: (id: string) => void
}) {
  const qc = useQueryClient()
  const [kind, setKind] = useState<PersonKind>(defaultKind)
  const [name, setName] = useState("")
  const [organisation, setOrganisation] = useState("")
  const [group, setGroup] = useState(defaultGroup ?? "")
  const [error, setError] = useState<string | null>(null)
  const groups = flattenGroups(tree)

  const create = useMutation({
    mutationFn: () =>
      personsApi.create({
        kind,
        name: name.trim(),
        ...(kind === "person" && organisation.trim() ? { organisation: organisation.trim() } : {}),
        ...(group ? { group_ids: [group] } : {}),
      }),
    onSuccess: async (p) => {
      await invalidateRegister(qc)
      toast.success(t("persons.created", { id: p.person_id, pseudonym: p.pseudonym }))
      onCreated(p.person_id)
      onClose()
    },
    onError: (e) => setError(plainError(e)),
  })

  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>{t("persons.new_person")}</DialogTitle>
          <DialogDescription>{t("persons.new_person_help")}</DialogDescription>
        </DialogHeader>
        <form
          className="flex flex-col gap-3"
          onSubmit={(e) => {
            e.preventDefault()
            setError(null)
            create.mutate()
          }}
        >
          <div className="seg" role="radiogroup" aria-label={t("common.type")} style={{ alignSelf: "flex-start" }}>
            {KINDS.map((k) => (
              <button key={k} type="button" role="radio" aria-checked={kind === k} className={cn("s", kind === k && "on")} onClick={() => setKind(k)}>
                {kindLabel(k)}
              </button>
            ))}
          </div>
          <Field label={t("common.nom")}>
            <Input value={name} autoFocus onChange={(e) => setName(e.target.value)} />
          </Field>
          {kind === "person" && (
            <Field label={t("common.organisation")}>
              <Input value={organisation} onChange={(e) => setOrganisation(e.target.value)} />
            </Field>
          )}
          <Field label={t("persons.group")}>
            <NativeSelect value={group} onChange={(e) => setGroup(e.target.value)}>
              <option value="">{t("persons.no_group")}</option>
              {groups.map((g) => (
                <option key={g.group_id} value={g.group_id}>
                  {g.path}
                </option>
              ))}
            </NativeSelect>
          </Field>
          {error && <Alerts messages={[error]} />}
          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              {t("common.annuler")}
            </Button>
            <Button type="submit" disabled={!name.trim() || create.isPending}>
              {t("persons.create")}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}
